        let nat = tmPartyNatural(frames);
        for (let s = 0; s < 4; s++) {
            let t = tmPartyTarget(s),
                n = nat[s];

            tmPartyOffsets[s] = t && n ? [t[0] - n[0], t[1] - n[1]] : [0, 0];
        }
        for (let row of frames.children) tmPartyRowApply(row, tmPartyRowClass(row));
